SELECT CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 1200 THEN 'mid' ELSE 'low' END AS revenue_bucket, COUNT(DISTINCT i.quantity) AS unique_stores, COUNT(*) AS cnt FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.revenue > 2800 GROUP BY CASE WHEN ss.revenue >= 3300 THEN 'high' WHEN ss.revenue >= 1200 THEN 'mid' ELSE 'low' END;
